primaryQuery:
run: order_items -> {
  aggregate:
    total_sales is sale_price.sum()
    customers is count(user_id)
} -> {
  select:
    total_sales
    customers
    avg_spend_per_customer is round(total_sales / customers, 4)
}

verifyQuery:
run: order_items -> {
  group_by: user_id
  aggregate: spend is sale_price.sum()
} -> {
  aggregate: total_sales is spend.sum(), customers is count()
} -> {
  select: total_sales, customers, avg_spend_per_customer is round(total_sales / customers, 4)
}
